@import "./fonts.css";

@layer tokens, components;

@layer tokens {
  :root {
    color-scheme: light;

    --text-heading: #111;
    --text-body: #444;
    --text-sub: #5c5c5c;
    --text-disabled: #767676;
    --link: var(--text-heading);

    --font-sans: var(--font-onest, "Onest"), system-ui, sans-serif;
    --font-mono: var(--font-dm-mono, "DM Mono"), ui-monospace, monospace;

    --bg: #fff;
    --bg-hover: #f3f2f1;
    --bg-well: #e8e6e4;
    --bg-overlay: var(--bg);

    --ink: #111;
    --on-ink: #fff;
    --key: #a2c7ff;
    --key-line: #221898;
    --on-key: #111;
    --shine: #fff;
    --chrome-mix: #fff;
    --error: #8f3232;
    --on-error: #111;
    --success: #2f6b3a;
    --on-success: #111;
    --warning: #8a5a12;
    --on-warning: #111;
    --info: #2c4a6e;
    --on-info: #111;
    --line: color-mix(in srgb, var(--text-heading) 18%, transparent);
    --line-strong: color-mix(in srgb, var(--text-heading) 32%, transparent);
    --focus: color-mix(in srgb, var(--text-heading) 70%, transparent);
    --selection: color-mix(in srgb, var(--key) 42%, transparent);

    --accent-surface: color-mix(in srgb, var(--key) 14%, var(--bg));
    --accent-line: color-mix(in srgb, var(--key-line) 42%, transparent);
    --accent-ink: var(--key-line);
    --success-surface: color-mix(in srgb, var(--success) 12%, var(--bg));
    --success-line: color-mix(in srgb, var(--success) 42%, transparent);
    --warning-surface: color-mix(in srgb, var(--warning) 12%, var(--bg));
    --warning-line: color-mix(in srgb, var(--warning) 42%, transparent);
    --error-surface: color-mix(in srgb, var(--error) 12%, var(--bg));
    --error-line: color-mix(in srgb, var(--error) 42%, transparent);
    --info-surface: color-mix(in srgb, var(--info) 12%, var(--bg));
    --info-line: color-mix(in srgb, var(--info) 42%, transparent);

    --z-base: 0;
    --z-nav: 10;
    --z-overlay: 20;
    --z-toast: 30;

    --bp-md: 48rem;

    --ratio: 1.25;

    --type-md: 1rem;
    --type-sm: calc(var(--type-md) / var(--ratio));
    --type-xs: calc(var(--type-sm) / var(--ratio));
    --type-lg: calc(var(--type-md) * var(--ratio));
    --type-xl: calc(var(--type-lg) * var(--ratio));
    --type-2xl: calc(var(--type-xl) * var(--ratio));
    --type-mono: 0.875rem;
    --type-mono-sm: calc(var(--type-mono) / var(--ratio));

    --control: calc(
      var(--type-md) * var(--leading-tight) + var(--space-4) * 2
    );

    --leading-tight: var(--ratio);
    --leading: calc(var(--ratio) * var(--ratio));

    --weight-regular: 400;
    --weight-medium: 500;

    --space: 0.25rem;
    --space-1: var(--space);
    --space-2: calc(var(--space-1) * var(--ratio));
    --space-3: calc(var(--space-2) * var(--ratio));
    --space-4: calc(var(--space-3) * var(--ratio));
    --space-5: calc(var(--space-4) * var(--ratio));
    --space-6: calc(var(--space-5) * var(--ratio));
    --space-7: calc(var(--space-6) * var(--ratio));
    --space-8: calc(var(--space-7) * var(--ratio));
    --space-9: calc(var(--space-8) * var(--ratio));
    --space-10: calc(var(--space-9) * var(--ratio));
    --space-11: calc(var(--space-10) * var(--ratio));
    --space-12: calc(var(--space-11) * var(--ratio));
    --space-13: calc(var(--space-12) * var(--ratio));
    --space-14: calc(var(--space-13) * var(--ratio));

    --radius: var(--space-3);
    --inset-list: var(--space-2);
    --radius-list: calc(var(--radius) + var(--inset-list));

    --highlight: oklch(1 0 0 / 62%);
    --shade: oklch(0 0 0 / 28%);

    --tool:
      inset 0 1px 0 0 var(--highlight),
      inset 0 -1px 0 0 var(--shade),
      inset 0 0 0 0 transparent,
      inset 0 0 0 0 transparent;
    --lift:
      0 1px 0 color-mix(in srgb, var(--shade) 90%, transparent),
      0 2px 0 color-mix(in srgb, var(--shade) 50%, transparent);
    --raise: var(--tool), var(--lift);
    --flat:
      inset 0 0 0 0 transparent,
      inset 0 0 0 0 transparent,
      inset 0 0 0 0 transparent,
      inset 0 0 0 0 transparent,
      0 0 0 transparent,
      0 0 0 transparent;
    --well:
      inset 0 1px 0 var(--shade),
      inset 0 2px 0 color-mix(in srgb, var(--shade) 60%, transparent),
      inset 0 4px 6px color-mix(in srgb, var(--shade) 80%, transparent),
      inset 0 -1px 0 var(--highlight);
    --press:
      inset 0 2px 3px color-mix(in srgb, var(--shade) 55%, transparent),
      inset 0 0 0 0 transparent,
      inset 0 0 0 0 transparent,
      inset 0 0 0 0 transparent,
      0 0 0 transparent,
      0 0 0 transparent;
    --face: linear-gradient(
      180deg,
      #fbfbfb 0%,
      #ededed 42%,
      #e4e4e4 100%
    );
    --face-line: #626262;
    --face-hover: linear-gradient(
      180deg,
      #ffffff 0%,
      #f3f3f3 42%,
      #e8e8e8 100%
    );
    --face-press: linear-gradient(
      180deg,
      #ededed 0%,
      #e4e4e4 50%,
      #d8d8d8 100%
    );
    --float: 0 8px 20px color-mix(in srgb, var(--text-heading) 12%, transparent);
    --float-press: 0 2px 8px color-mix(in srgb, var(--text-heading) 10%, transparent);

    --ns-key: var(--key);
    --ns-on-key: var(--on-key);
    --key-face: linear-gradient(
      180deg,
      #edf4ff 0%,
      #d6e7ff 18%,
      #a2c7ff 50%,
      #99cbf8 80%,
      #a2d2f7 100%
    );
    --key-face-hover: linear-gradient(
      180deg,
      #f4f8ff 0%,
      #e4efff 18%,
      #b4d2ff 50%,
      #aad4fa 80%,
      #b4def9 100%
    );
    --key-face-press: linear-gradient(
      180deg,
      #d6e7ff 0%,
      #a2c7ff 45%,
      #8ab8f4 100%
    );

    --ease: cubic-bezier(0.22, 1, 0.36, 1);
    --duration: 200ms;
  }

  @media (prefers-reduced-motion: reduce) {
    :root {
      --duration: 0ms;
    }
  }

  [data-density="compact"] {
    --control: calc(
      var(--type-sm) * var(--leading-tight) + var(--space-3) * 2
    );
  }

  @media (prefers-color-scheme: dark) {
    :root:not(.light) {
      color-scheme: dark;
      --text-heading: #f5f5f5;
      --text-body: #b3b3b3;
      --text-sub: #a3a3a3;
      --text-disabled: #8a8a8a;
      --bg: #1a1a1a;
      --bg-hover: #242424;
      --bg-well: #111;
      --ink: #f5f5f5;
      --on-ink: #111;
      --shine: #303030;
     --chrome-mix: #111;
      --error: #b33b3b;
      --on-error: #f5f5f5;
      --success: #4a9a58;
      --on-success: #f5f5f5;
      --warning: #c4922a;
      --on-warning: #f5f5f5;
      --info: #6a92c4;
      --on-info: #f5f5f5;
      --highlight: oklch(1 0 0 / 36%);
      --shade: oklch(0 0 0 / 58%);
      --lift:
        0 1px 0 oklch(0 0 0 / 40%),
        0 2px 0 oklch(0 0 0 / 16%);
      --float: 0 8px 20px oklch(0 0 0 / 45%);
      --float-press: 0 2px 8px oklch(0 0 0 / 35%);
      --on-key: #f5f5f5;
      --key: #b4d2ff;
      --key-line: var(--key);
      --accent-ink: var(--key);
      --accent-line: color-mix(in srgb, var(--key) 42%, transparent);
      --face-line: #737373;
      --face: linear-gradient(
            180deg,
            #363636 0%,
            #2a2a2a 42%,
            #202020 100%
          );
      --face-hover: linear-gradient(
            180deg,
            #424242 0%,
            #333333 42%,
            #282828 100%
          );
      --face-press: linear-gradient(
            180deg,
            #2a2a2a 0%,
            #222222 50%,
            #1a1a1a 100%
          );
      --key-face: linear-gradient(
        180deg,
        color-mix(in srgb, var(--key) 18%, var(--chrome-mix)) 0%,
        color-mix(in srgb, var(--key) 38%, var(--chrome-mix)) 18%,
        color-mix(in srgb, var(--key) 58%, var(--chrome-mix)) 50%,
        color-mix(in srgb, var(--key) 62%, var(--chrome-mix)) 80%,
        color-mix(in srgb, var(--key) 55%, var(--chrome-mix)) 100%
      );
      --key-face-hover: linear-gradient(
        180deg,
        color-mix(in srgb, var(--key) 12%, var(--chrome-mix)) 0%,
        color-mix(in srgb, var(--key) 30%, var(--chrome-mix)) 18%,
        color-mix(in srgb, var(--key) 50%, var(--chrome-mix)) 50%,
        color-mix(in srgb, var(--key) 54%, var(--chrome-mix)) 100%
      );
      --key-face-press: linear-gradient(
        180deg,
        color-mix(in srgb, var(--key) 38%, var(--chrome-mix)) 0%,
        color-mix(in srgb, var(--key) 62%, var(--chrome-mix)) 50%,
        color-mix(in srgb, var(--key) 72%, var(--chrome-mix)) 100%
      );
    }
  }

  :root.dark {
    color-scheme: dark;
    --text-heading: #f5f5f5;
    --text-body: #b3b3b3;
    --text-sub: #a3a3a3;
    --text-disabled: #8a8a8a;
    --bg: #1a1a1a;
    --bg-hover: #242424;
    --bg-well: #111;
    --ink: #f5f5f5;
    --on-ink: #111;
    --shine: #303030;
    --chrome-mix: #111;
    --error: #b33b3b;
    --on-error: #f5f5f5;
    --success: #4a9a58;
    --on-success: #f5f5f5;
    --warning: #c4922a;
    --on-warning: #f5f5f5;
    --info: #6a92c4;
    --on-info: #f5f5f5;
    --highlight: oklch(1 0 0 / 36%);
    --shade: oklch(0 0 0 / 58%);
    --lift:
      0 1px 0 oklch(0 0 0 / 40%),
      0 2px 0 oklch(0 0 0 / 16%);
    --float: 0 8px 20px oklch(0 0 0 / 45%);
    --float-press: 0 2px 8px oklch(0 0 0 / 35%);
    --on-key: #f5f5f5;
    --key: #b4d2ff;
    --key-line: var(--key);
    --accent-ink: var(--key);
    --accent-line: color-mix(in srgb, var(--key) 42%, transparent);
    --face-line: #737373;
    --face: linear-gradient(
      180deg,
      #363636 0%,
      #2a2a2a 42%,
      #202020 100%
    );
    --face-hover: linear-gradient(
      180deg,
      #424242 0%,
      #333333 42%,
      #282828 100%
    );
    --face-press: linear-gradient(
      180deg,
      #2a2a2a 0%,
      #222222 50%,
      #1a1a1a 100%
    );
    --key-face: linear-gradient(
      180deg,
      color-mix(in srgb, var(--key) 18%, var(--chrome-mix)) 0%,
      color-mix(in srgb, var(--key) 38%, var(--chrome-mix)) 18%,
      color-mix(in srgb, var(--key) 58%, var(--chrome-mix)) 50%,
      color-mix(in srgb, var(--key) 62%, var(--chrome-mix)) 80%,
      color-mix(in srgb, var(--key) 55%, var(--chrome-mix)) 100%
    );
    --key-face-hover: linear-gradient(
      180deg,
      color-mix(in srgb, var(--key) 12%, var(--chrome-mix)) 0%,
      color-mix(in srgb, var(--key) 30%, var(--chrome-mix)) 18%,
      color-mix(in srgb, var(--key) 50%, var(--chrome-mix)) 50%,
      color-mix(in srgb, var(--key) 54%, var(--chrome-mix)) 100%
    );
    --key-face-press: linear-gradient(
      180deg,
      color-mix(in srgb, var(--key) 38%, var(--chrome-mix)) 0%,
      color-mix(in srgb, var(--key) 62%, var(--chrome-mix)) 50%,
      color-mix(in srgb, var(--key) 72%, var(--chrome-mix)) 100%
    );
  }

  :root.light {
    color-scheme: light;
    --text-heading: #111;
    --text-body: #444;
    --text-sub: #5c5c5c;
    --text-disabled: #767676;
    --bg: #fff;
    --bg-hover: #f3f2f1;
    --bg-well: #e8e6e4;
    --ink: #111;
    --on-ink: #fff;
    --shine: #fff;
    --error: #8f3232;
    --on-error: #111;
    --success: #2f6b3a;
    --on-success: #111;
    --warning: #8a5a12;
    --on-warning: #111;
    --info: #2c4a6e;
    --on-info: #111;
    --highlight: oklch(1 0 0 / 62%);
    --shade: oklch(0 0 0 / 28%);
  }
}

@layer components {
  .ns-sr {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
  }
}

:focus:not(:focus-visible) {
  outline: none;
}

:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}
